1735	    /// Clears the bridging flag armed before a bridge poll, closing
1736	    /// the window in which the parse stage writes idle wakes.
1737	    fn clearBridging(pipeline: *Pipeline) void {
1738	        pipeline.mutex.lockUncancelable(global.io());
1739	        defer pipeline.mutex.unlock(global.io());
1740	        pipeline.bridging = false;
1741	    }
