1743	    /// Sets the QoS class of the calling thread for the read pipeline
1744	    /// (macOS only). Both pipeline threads feed content the user is
1745	    /// actively watching, and at default QoS the scheduler may place
1746	    /// them on efficiency cores with wakeup latencies that are large
1747	    /// compared to the ~10us cadence of the pty producer/consumer
1748	    /// dance. Measured on an M4 Max, this results in a 15% throughput
1749	    /// difference (on the change, not 15% total).
1750	    fn setQosClass() void {
1751	        internal_os.macos.setQosClass(.user_initiated) catch |err| {
1752	            log.warn("error setting QoS class err={}", .{err});
1753	        };
1754	    }
